                    IICHIVaultFactory(msg.sender).ammName(),
                    "-",
                    allowToken0 ? token0Symbol : token1Symbol,
                    "-",
                    allowToken0 ? token1Symbol : token0Symbol,
                    "-",
                    Strings.toString(uniswapPool.fee())
                )
            );
    }
}

