// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

/// @title Aegis Vault Factory Events
/// @notice Contains all events emitted by the AegisVaultFactory contract
interface IAegisVaultFactoryEvents {
    /// @notice Emitted when the AegisVaultFactory is deployed
    /// @param sender The address that deployed the factory
    /// @param ichiVaultFactory The address of the ICHI Vault Factory
    /// @param quoter The address of the Uniswap V3 Quoter
    /// @param aegisVaultImplementation The address of the AegisVault implementation
    /// @param aegisVaultERC20Implementation The address of the AegisVaultERC20 implementation
    /// @param ammName The name of the AMM
    event DeployAegisVaultFactory(
        address indexed sender,
        address ichiVaultFactory,
        address quoter,
        address aegisVaultImplementation,
        address aegisVaultERC20Implementation,
        string ammName
    );

    /// @notice Emitted when a new AegisVault is created
    /// @param sender The address that created the vault
    /// @param aegisVault The address of the newly created AegisVault
    /// @param depositToken The address of the depositToken
    /// @param targetToken The address of the targetToken
    /// @param depositVault The address of the depositVault
    /// @param targetVault The address of the targetVault
    /// @param count The total number of AegisVaults created so far
    event AegisVaultCreated(
        address indexed sender,
        address aegisVault,
        address depositToken,
        address targetToken,
        address depositVault,
        address targetVault,
        uint256 count
    );

    /// @notice Emitted when the default fee recipient is changed
    /// @param sender The address that changed the fee recipient
    /// @param feeRecipient The new default fee recipient address
    event SetDefaultFeeRecipient(address indexed sender, address feeRecipient);

    /// @notice Emitted when the default base fee is changed
    /// @param sender The address that changed the base fee
    /// @param baseFee The new default base fee
    event SetDefaultBaseFee(address indexed sender, uint256 baseFee);
}

// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;

import { IQuoter } from "@uniswap/v3-periphery/contracts/interfaces/IQuoter.sol";

/// @title Aegis Vault Factory Immutables
/// @notice Defines the immutable state variables for the Aegis Vault Factory
interface IAegisVaultFactoryImmutables {
    /// @notice The address of the ICHIVaultFactory contract
    function ichiVaultFactory() external view returns (address);

    /// @notice The name of the Automated Market Maker (AMM) used
    function ammName() external view returns (string memory);

    /// @notice The address of the Uniswap V3 Quoter contract
    function quoter() external view returns (IQuoter);

    /// @notice The address of the AegisVault implementation contract
    function aegisVaultImplementation() external view returns (address);

    /// @notice The address of the AegisVaultERC20 implementation contract
    function aegisVaultERC20Implementation() external view returns (address);
}

// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

/// @title Aegis Vault Factory Owner Actions
/// @notice Contains functions that can only be called by the owner of the Aegis Vault Factory
interface IAegisVaultFactoryOwnerActions {
    /// @notice Parameters for creating an AegisVault
    /// @param depositToken The token the Aegis vault accepts for deposits
    /// @param depositVault The address of the ICHIVault used for depositToken
    /// @param depositVaultDeployer The address of the deployer of the depositVault
    /// @param targetVault The address of the ICHIVault used for targetToken
    /// @param targetVaultDeployer The address of the deployer of the target vault
    /// @param isERC20 If true, the Aegis vault shares will be ERC20 tokens
    struct CreateAegisVaultParams {
        address depositToken;
        address depositVault;
        address depositVaultDeployer;
        address targetVault;
        address targetVaultDeployer;
        bool isERC20;
    }

    /// @notice Creates a new instance of AegisVault for the specified token and its vaults
    /// @dev This function can create multiple Aegis vaults for the same pair of ICHIVaults
    /// @param createAegisVaultParams A struct containing the parameters for creating the AegisVault
    /// @return aegisVault The address of the newly created AegisVault
    function createAegisVault(CreateAegisVaultParams memory createAegisVaultParams) external returns (address aegisVault);

    /// @notice Sets the default fee recipient account address
    /// @dev This address will receive a portion of the fees collected by Aegis vaults
    /// @param _feeRecipient The address to set as the default fee recipient
    function setDefaultFeeRecipient(address _feeRecipient) external;

    /// @notice Sets the default base fee percentage for newly created Aegis vaults
    /// @dev This fee is applied to the targetTokens transferred on rebalances
    /// @param _baseFee The default fee percentage (100 = 1%, 10000 = 100%)
    function setDefaultBaseFee(uint256 _baseFee) external;
}

