// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

import "./IAegisVaultStructs.sol";

/// @title Aegis Vault Events Interface
/// @notice Contains all events emitted by the Aegis vault
interface IAegisVaultEvents {
    /// @notice Emitted when an Aegis vault is deployed
    /// @param sender The address that deployed the vault(typically the AegisVaultFactory)
    /// @param depositToken The address of the deposit token
    /// @param targetToken The address of the target token
    /// @param depositVault The address of the deposit ICHI vault
    /// @param targetVault The address of the target ICHI vault
    /// @param owner The address of the vault owner
    /// @param vaultIndex The index of the vault in the factory
    event DeployAegisVault(
        address indexed sender,
        address depositToken,
        address targetToken,
        address depositVault,
        address targetVault,
        address owner,
        uint256 vaultIndex
    );

    /// @notice Emitted when the TWAP period is updated
    /// @param sender The address that updated the TWAP period
    /// @param newTwapPeriod The new TWAP period
    event SetTwapPeriod(address sender, uint32 newTwapPeriod);

    /// @notice Emitted when the maximum volatility threshold is updated
    /// @param sender The address that updated the threshold
    /// @param newMaxVolatility The new maximum volatility threshold
    event SetMaxVolatility(address sender, uint256 newMaxVolatility);

    /// @notice Emitted when a deposit is made to the vault
    /// @param sender The address that initiated the deposit
    /// @param to The address receiving the minted Aegis shares
    /// @param shares The number of Aegis shares minted
    /// @param depositTokenAmount The amount of deposit tokens deposited
    /// @param depositSharesAmount The amount of deposit vault shares deposited
    event Deposit(address indexed sender, address indexed to, uint256 shares, uint256 depositTokenAmount, uint256 depositSharesAmount);

    /// @notice Emitted when a withdrawal is made from the vault
    /// @param sender The address that initiated the withdrawal
    /// @param to The address receiving the withdrawn assets
    /// @param aegisShares The number of Aegis shares that were requested to be burned
    /// @param slippage The slippage data for the withdrawal
    event Withdraw(address indexed sender, address indexed to, uint256 aegisShares, IAegisVaultStructs.WithdrawSlippageData slippage);

    /// @notice Emitted when withdrawal fees are collected
    /// @param sender The address that initiated the withdrawal
    /// @param to The address receiving the fees
    /// @param depositShareFees The amount of deposit vault shares collected as fees
    /// @param targetSharefee The amount of target vault shares collected as fees
    event WithdrawFees(address indexed sender, address indexed to, uint256 depositShareFees, uint256 targetSharefee);

    /// @notice Emitted when a rebalance operation is performed
    /// @param rebalancePct The percentage of assets rebalanced
    /// @param withdrawnShares The amount of shares withdrawn from the deposit vault
    /// @param depositTokenBalance The amount of deposit tokens re-deposited to the deposit vault
    /// @param targetTokenBalance The amount of target tokens re-deposited to the target vault
    /// @param fees The amount of fees collected during the rebalance
    event Rebalance(uint256 rebalancePct, uint256 withdrawnShares, uint256 depositTokenBalance, uint256 targetTokenBalance, uint256 fees);

    /// @notice Emitted when the hysteresis threshold is updated
    /// @param sender The address that updated the threshold
    /// @param hysteresis The new hysteresis threshold
    event SetHysteresis(address indexed sender, uint256 hysteresis);

    /// @notice Emitted when the pending deposit threshold is updated
    /// @param sender The address that updated the threshold
    /// @param pendingThreshold The new pending deposit threshold
    event SetPendingThreshold(address indexed sender, uint256 pendingThreshold);

    /// @notice Emitted when the maximum rebalance threshold is updated
    /// @param sender The address that updated the threshold
    /// @param maxRebalanceThreshold The new maximum rebalance threshold
    event SetMaxRebalanceThreshold(address indexed sender, uint256 maxRebalanceThreshold);

    /// @notice Emitted when the excess target token threshold is updated
    /// @param sender The address that updated the threshold
    /// @param excessTargetTokenThreshold The new excess target token threshold
    event SetExcessTargetTokenThreshold(address indexed sender, uint256 excessTargetTokenThreshold);

    /// @notice Emitted when the fee recipient is updated
    /// @param sender The address that updated the fee recipient
    /// @param feeRecipient The new fee recipient address
    event SetFeeRecipient(address indexed sender, address feeRecipient);

    /// @notice Emitted when the fees are updated
    /// @param sender The address that updated the fees
    /// @param baseFee The new base fee
    /// @param withdrawFee The new withdraw fee
    event SetFees(address indexed sender, uint256 baseFee, uint256 withdrawFee);

    /// @notice Emitted when a fee update is scheduled
    /// @param sender The address that scheduled the fee update
    /// @param baseFee The scheduled base fee
    /// @param withdrawFee The scheduled withdraw fee
    event ScheduleSetFees(address indexed sender, uint256 baseFee, uint256 withdrawFee);

    /// @notice Emitted when doCheckImpliedSlippage is toggled
    /// @param sender The address that scheduled the fee update
    /// @param doCheckImpliedSlippage the value that doCheckImpliedSlippage is toggled to
    event CheckImpliedSlippage(address indexed sender, bool doCheckImpliedSlippage);

    /// @notice Emitted when extra tokens are swept from the contract
    /// @param sender The address initiating the sweep
    /// @param token The token being swept
    /// @param recipient The recipient of the swept tokens
    /// @param amount The amount of tokens swept
    event SweepExtraTokens(address sender, address indexed token, address indexed recipient, uint256 amount);
}

src/interfaces/vault/IAegisVaultOwnerAct.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

/// @title Aegis Vault Admin Actions Interface
/// @notice Contains all actions that can only be performed by addresses with the DEFAULT_ADMIN_ROLE
interface IAegisVaultOwnerActions {
    /// @notice Pauses deposits and rebalances on the Aegis vault
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    function pause() external;

    /// @notice Unpauses deposits and rebalances on the Aegis vault
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    function unpause() external;

    /// @notice Resets the approvals for the ICHI vaults
    /// @dev This function should be called if the allowance for the ICHI vaults needs to be reset
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    function resetICHIVaultApprovals() external;

    /// @notice Transfers any extra ERC20 tokens held by the contract to a specified recipient
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev Extra tokens are any ERC20 tokens other than depositToken, targetToken, depositVault, and targetVault
    /// @dev The function will revert if there are no extra tokens to sweep
    /// @param _token The address of the ERC20 token to be swept
    /// @param _recipient The address of the recipient to receive the swept tokens
    /// @notice Emits a SweepExtraTokens event after successful execution
    function sweepExtraTokens(address _token, address _recipient) external;

    /// @notice Sets the pending deposit threshold for the underlying vaults (Deposit and Target)
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new threshold must be a valid percentage expressed in BSP
    /// @param _newPendingThreshold The new pending deposit threshold to be set
    /// @notice Emits a SetPendingThreshold event after successful execution
    function setPendingThreshold(uint256 _newPendingThreshold) external;

    /// @notice Sets the maximum rebalance threshold for the vault
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new threshold must be a valid percentage expressed in BSP
    /// @param _newMaxRebalanceThreshold The new maximum rebalance threshold to be set
    /// @notice Emits a SetMaxRebalanceThreshold event after successful execution
    function setMaxRebalanceThreshold(uint256 _newMaxRebalanceThreshold) external;

    /// @notice Sets the excess target token threshold for the Deposit vault
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new threshold must be a valid percentage expressed in BSP
    /// @param _newExcessTargetTokenThreshold The new excess target token threshold to be set
    /// @notice Emits a SetExcessTargetTokenThreshold event after successful execution
    function setExcessTargetTokenThreshold(uint256 _newExcessTargetTokenThreshold) external;

    /// @notice Sets the maximum volatility threshold for the underlying vaults (Deposit and Target)
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new threshold must be greater than 0 and expressed as a FP U18
    /// @param _newMaxVolatility The new maximum volatility threshold to be set
    /// @notice Emits a SetMaxVolatility event after successful execution
    function setMaxVolatility(uint256 _newMaxVolatility) external;

    /// @notice Sets the delta value used in determining whether tokens being deposited by the user
    /// are approximatelly equal to the resulting users tokens after the deposit
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new threshold must be greater than 0, less than 10001 and expressed as a FP U18
    /// @param _newMaxDelta The new maximum volatility threshold to be set
    function setMaxDelta(uint256 _newMaxDelta) external;

    /// @notice Sets the hysteresis threshold for price change checks
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @param _hysteresis The new hysteresis threshold (expressed as a FP U18, 1e16 = 0.01 = 1%)
    /// @notice Emits a SetHysteresis event after successful execution
    function setHysteresis(uint256 _hysteresis) external;

    /// @notice Sets the time-weighted average price (TWAP) period for the vault (used for volatility checks)
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new period must be greater than 0
    /// @param _newTwapPeriod The new TWAP period to be set in seconds
    /// @notice Emits a SetTwapPeriod event after successful execution
    function setTwapPeriod(uint32 _newTwapPeriod) external;

    /// @notice Sets the fee recipient account address
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new address must not be the zero address
    /// @param _feeRecipient The new fee recipient account address
    /// @notice Emits a SetFeeRecipient event after successful execution
    function setFeeRecipient(address _feeRecipient) external;

    /// @notice Schedules a call to set the fee percentages
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @dev The new fee percentages must be valid percentages expressed in BSP
    /// @param _baseFee The new base fee percentage in BSP (100 = 1%, 10000 = 100%)
    /// @param _withdrawFee The new withdraw fee percentage in BSP (100 = 1%, 10000 = 100%)
    /// @notice Emits a ScheduleSetFees event after successful execution
    function scheduleSetFees(uint256 _baseFee, uint256 _withdrawFee) external;

    /// @notice Executes the scheduled fee update
    /// @dev Can be called by anyone, but only after the scheduled time has passed
    /// @notice Emits a SetFees event after successful execution
    function executeSetFees() external;

    function setCheckImpliedSlippage(bool _doCheckImpliedSlippage) external;

    /// @notice Claims rewards from a Merkle distributor
    /// @dev Can only be called by an address with the DEFAULT_ADMIN_ROLE
    /// @param merkleDistributor The address of the Merkle distributor contract
    /// @param recipient The address to receive the claimed rewards
    /// @param users The list of user addresses for which to claim
    /// @param tokens The list of token addresses to claim
    /// @param amounts The list of amounts to claim for each token
    /// @param proofs The Merkle proofs for each claim
    function claim(
        address merkleDistributor,
        address recipient,
        address[] calldata users,
        address[] calldata tokens,
        uint256[] calldata amounts,
        bytes32[][] calldata proofs
    )
        external;
}

src/interfaces/vault/IAegisVaultState.so.content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

/// @title Aegis Vault State Interface
/// @notice Defines read-only functions to access the current state of the Aegis vault
/// @dev U18 FP refers to unsigned fixed-point integers with 18 decimals of precision
interface IAegisVaultState {
    /// @notice The time-weighted average price (TWAP) period(in seconds) used for price calculations
    function twapPeriod() external view returns (uint32);

    /// @notice The maximum allowed volatility for price changes expressed as a FP U18
    function maxVolatility() external view returns (uint256);

    /// @notice This value is used in determining whether tokens being deposited by the user
    /// are approximatelly equal to the resulting users tokens after the deposit
    function maxDelta() external view returns (uint256);

    /// @notice The hysteresis threshold for price change checks expressed as a FP U18
    function hysteresis() external view returns (uint256);

    /// @notice The threshold for pending deposits in the underlying vaults expressed in BSP
    function pendingThreshold() external view returns (uint256);

    /// @notice The maximum threshold for rebalancing operations expressed in BSP
    function maxRebalanceThreshold() external view returns (uint256);

    /// @notice The threshold for excess target tokens in the deposit vault expressed in BSP
    function excessTargetTokenThreshold() external view returns (uint256);

    /// @notice The address that receives fees from the vault
    function feeRecipient() external view returns (address);

    /// @notice The base fee percentage(expressed in BSP) charged on rebalancing operations
    function baseFee() external view returns (uint256);

    /// @notice The fee percentage(expressed in BSP) charged on withdrawals
    function withdrawFee() external view returns (uint256);

    /// @notice The pending fee update information
    /// @return _timestamp The timestamp when the pending fees can be executed
    /// _baseFee The pending base fee as a percentage in basis points (100 = 1%, 10000 = 100%)
    /// _withdrawFee The pending withdraw fee as a percentage in basis points (100 = 1%, 10000 = 100%)
    /// NB: we don't add return tag to _baseFee and _withdrawFee due to compiler bug
    function pendingFees() external view returns (uint256 _timestamp, uint256 _baseFee, uint256 _withdrawFee);

    /// @notice whether or not the implied swap slippage check and deposit devaluation is done
    function doCheckImpliedSlippage() external view returns (bool);
}

src/interfaces/vault/IAegisVaultStructs..content:
// SPDX-License-Identifier: GPL-2.0-or-later
pragma solidity >=0.5.0;
pragma abicoder v2;

/// @title Aegis Vault Structs Interface
/// @notice Defines the structures used in the Aegis vault system
interface IAegisVaultStructs {
    /// @notice Struct to hold withdrawal slippage data
    /// @dev Used to specify minimum acceptable amounts for withdrawals and to return actual withdrawn amounts
    struct WithdrawSlippageData {
        uint256 depositTokenAmount;
        uint256 targetTokenAmount;
        // NB: depositSharesAmount in the case of WithdrawType.TargetOnly is NOT the depositShares minted
        // but is rather the aegisShares representing the value of depositTokenAmount that was re-deposited
        uint256 depositSharesAmount;
        uint256 targetSharesAmount;
    }
}

